messages.content:
Absolutely — here’s a powerful single-file social media app in React + TypeScript. Drop this into `src/App.tsx` and it will give you a modern social media dashboard with:

- Dark/light mode
- Feed with posts
- Like/comment actions
- Story section
- Trending sidebar
- Search
- Composer to create posts
- Responsive layout
- Strong visual design

This is a great “src” foundation for a serious social media product.

```tsx
import React, { useMemo, useState } from "react";

type Story = {
  id: number;
  user: string;
  avatar: string;
  active: boolean;
};

type Post = {
  id: number;
  author: string;
  handle: string;
  role: string;
  avatar: string;
  time: string;
  content: string;
  image?: string;
  likes: number;
  comments: number;
  shares: number;
  liked: boolean;
};

const stories: Story[] = [
  { id: 1, user: "Ava", avatar: "A", active: true },
  { id: 2, user: "Leo", avatar: "L", active: true },
  { id: 3, user: "Zoe", avatar: "Z", active: false },
  { id: 4, user: "Mia", avatar: "M", active: true },
  { id: 5, user: "Kai", avatar: "K", active: false },
  { id: 6, user: "Nia", avatar: "N", active: true },
];

const initialPosts: Post[] = [
  {
    id: 1,
    author: "Maya Chen",
    handle: "@mayac",
    role: "Product Designer",
    avatar: "M",
    time: "2h ago",
    content:
      "Designing a product that feels human is the real challenge. Great UX is not just beautiful — it removes friction. What makes a product feel intuitive to you?",
    image:
      "https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&w=1200&q=80",
    likes: 1240,
    comments: 336,
    shares: 89,
    liked: false,
  },
  {
    id: 2,
    author: "Jordan Lee",
    handle: "@jlee",
    role: "Fullstack Engineer",
    avatar: "J",
    time: "4h ago",
    content:
      "Building scalable systems is less about writing more code and more about designing for change. A clean architecture saves you from chaos later.",
    likes: 980,
    comments: 214,
    shares: 52,
    liked: true,
  },
  {
    id: 3,
    author: "Sofia Patel",
    handle: "@sofiap",
    role: "AI Researcher",
    avatar: "S",
    time: "7h ago",
    content:
      "The most exciting AI products are the ones that enhance human ability, not replace it. Human insight + machine intelligence = real progress.",
    likes: 2100,
    comments: 540,
    shares: 170,
    liked: false,
  },
];

const trendingTopics = [
  "#AIRevolution",
  "#Web3Builders",
  "#RemoteWork",
  "#StartupLife",
  "#UXDesign",
  "#ProductStrategy",
];

const suggestedPeople = [
  { name: "Nina West", role: "Tech Writer", followed: false },
  { name: "Evan Cruz", role: "Systems Architect", followed: true },
  { name: "Rae Morgan", role: "Creator Economy", followed: false },
];

export default function App() {
  const [theme, setTheme] = useState<"dark" | "light">("dark");
  const [posts, setPosts] = useState<Post[]>(initialPosts);
  const [activeTab, setActiveTab] = useState("feed");
  const [composer, setComposer] = useState("");
  const [search, setSearch] = useState("");

  const filteredPosts = useMemo(() => {
    return posts.filter((post) => {
      const term = search.toLowerCase();
      return (
        post.author.toLowerCase().includes(term) ||
        post.handle.toLowerCase().includes(term) ||
        post.content.toLowerCase().includes(term)
      );
    });
  }, [posts, search]);

  const handleLike = (postId: number) => {
    setPosts((current) =>
      current.map((post) =>
        post.id === postId
          ? {
              ...post,
              liked: !post.liked,
              likes: post.liked ? post.likes - 1 : post.likes + 1,
            }
          : post
      )
    );
  };

  const handleAddPost = () => {
    if (!composer.trim()) return;

    const newPost: Post = {
      id: Date.now(),
      author: "You",
      handle: "@you",
      role: "Product Builder",
      avatar: "Y",
      time: "Just now",
      content: composer.trim(),
      likes: 0,
      comments: 0,
      shares: 0,
      liked: false,
    };

    setPosts((current) => [newPost, ...current]);
    setComposer("");
  };

  return (
    <div className={`app-shell ${theme}`}>
      <style>{`
        :root {
          --bg: #0b1020;
          --bg-soft: #121b2b;
          --card: #121a2c;
          --card-2: #1a263d;
          --text: #edf3ff;
          --muted: #9aa8c1;
          --primary: #7c9cff;
          --primary-2: #61dafb;
          --accent: #9b8cff;
          --success: #2dd4bf;
          --border: rgba(255,255,255,0.08);
          --shadow: rgba(6, 10, 20, 0.45);
        }

        .app-shell.light {
          --bg: #edf3ff;
          --bg-soft: #dfe9ff;
          --card: #ffffff;
          --card-2: #f3f7ff;
          --text: #0f172a;
          --muted: #53627b;
          --primary: #4f46e5;
          --primary-2: #0ea5e9;
          --accent: #8b5cf6;
          --success: #10b981;
          --border: rgba(15, 23, 42, 0.08);
          --shadow: rgba(30, 41, 59, 0.08);
        }

        * { box-sizing: border-box; }

        html, body, #root {
          margin: 0;
          min-height: 100%;
          font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
          background: var(--bg);
          color: var(--text);
        }

        body {
          background:
            radial-gradient(circle at top left, rgba(124, 156, 255, 0.22), transparent 30%),
            radial-gradient(circle at bottom right, rgba(97, 218, 251, 0.18), transparent 28%),
            var(--bg);
        }

        button, input, textarea {
          font: inherit;
        }

        .app-shell {
          min-height: 100vh;
          background: var(--bg);
          color: var(--text);
          transition: all 0.25s ease;
        }

        .layout {
          max-width: 1400px;
          margin: 0 auto;
          display: grid;
          grid-template-columns: 220px minmax(0, 1fr) 330px;
          gap: 28px;
          padding: 24px 18px 40px;
        }

        .sidebar, .rightbar {
          position: sticky;
          top: 18px;
          height: fit-content;
        }

        .card {
          background: var(--card);
          border: 1px solid var(--border);
          border-radius: 22px;
          box-shadow: 0 12px 28px var(--shadow);
        }

        .brand {
          display: flex;
          align-items: center;
          gap: 12px;
          padding: 18px 18px 10px;
        }

        .logo {
          width: 40px;
          height: 40px;
          border-radius: 14px;
          display: grid;
          place-items: center;
          background: linear-gradient(135deg, var(--primary), var(--primary-2));
          color: white;
          font-weight: 800;
          box-shadow: 0 10px 20px rgba(99, 102, 241, 0.4);
        }

        .brand-name {
          font-weight: 800;
          font-size: 1.1rem;
        }

        .nav {
          display: flex;
          flex-direction: column;
          gap: 10px;
          padding: 18px 12px 12px;
        }

        .nav-item {
          width: 100%;
          display: flex;
          align-items: center;
          gap: 12px;
          border: none;
          background: transparent;
          color: var(--text);
          border-radius: 14px;
          padding: 12px 14px;
          cursor: pointer;
          transition: 0.18s ease;
          font-weight: 600;
          text-align: left;
        }

        .nav-item:hover {
          background: rgba(124, 156, 255, 0.08);
        }

        .nav-item.active {
          background: linear-gradient(135deg, rgba(124, 156, 255, 0.18), rgba(97, 218, 251, 0.1));
          border: 1px solid rgba(124, 156, 255, 0.18);
        }

        .nav-icon {
          width: 32px;
          height: 32px;
          border-radius: 10px;
          display: grid;
          place-items: center;
          background: rgba(124, 156, 255, 0.12);
        }

        .profile-mini {
          margin-top: 18px;
          padding: 18px 16px;
        }

        .profile-head {
          display: flex;
          align-items: center;
          gap: 12px;
        }

        .avatar {
          width: 46px;
          height: 46px;
          border-radius: 50%;
          display: grid;
          place-items: center;
          background: linear-gradient(135deg, var(--primary), var(--accent));
          color: white;
          font-weight: 700;
        }

        .avatar.small {
          width: 34px;
          height: 34px;
          font-size: 0.78rem;
        }

        .muted {
          color: var(--muted);
        }

        .stats {
          margin-top: 18px;
          display: grid;
          grid-template-columns: repeat(3, minmax(0, 1fr));
          gap: 8px;
        }

        .stat-box {
          background: var(--bg-soft);
          border: 1px solid var(--border);
          border-radius: 14px;
          padding: 10px 8px;
          text-align: center;
        }

        .stat-value {
          font-size: 1.1rem;
          font-weight: 800;
        }

        .main-column {
          min-width: 0;
        }

        .topbar {
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: 16px;
          padding: 14px 16px;
          margin-bottom: 20px;
        }

        .search-wrap {
          flex: 1;
          display: flex;
          align-items: center;
          gap: 10px;
          background: var(--bg-soft);
          border: 1px solid var(--border);
          border-radius: 14px;
          padding: 10px 14px;
          min-width: 0;
        }

        .search-wrap input {
          background: transparent;
          border: none;
          color: var(--text);
          width: 100%;
          outline: none;
        }

        .search-wrap input::placeholder {
          color: var(--muted);
        }

        .actions {
          display: flex;
          align-items: center;
          gap: 12px;
        }

        .icon-btn {
          width: 42px;
          height: 42px;
          border: 1px solid var(--border);
          border-radius: 12px;
          background: var(--bg-soft);
          color: var(--text);
          cursor: pointer;
          display: grid;
          place-items: center;
          transition: transform 0.18s ease;
        }

        .icon-btn:hover {
          transform: translateY(-1px);
        }

        .theme-toggle {
          border: none;
          background: linear-gradient(135deg, var(--primary), var(--primary-2));
          color: white;
          border-radius: 12px;
          padding: 10px 14px;
          font-weight: 700;
          cursor: pointer;
          box-shadow: 0 10px 18px rgba(124, 156, 255, 0.28);
        }

        .hero {
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: 26px 24px;
          margin-bottom: 20px;
          overflow: hidden;
          position: relative;
        }

        .hero::before {
          content: "";
          position: absolute;
          inset: 0;
          background: linear-gradient(135deg, rgba(124, 156, 255, 0.18), rgba(97, 218, 251, 0.1));
          z-index: 0;
        }

        .hero > * {
          position: relative;
          z-index: 1;
        }

        .hero h1 {
          margin: 0 0 10px;
          font-size: clamp(1.8rem, 3vw, 2.5rem);
        }

        .hero p {
          margin: 0;
          color: var(--muted);
          max-width: 600px;
        }

        .cta-group {
          display: flex;
          align-items: center;
          gap: 10px;
          flex-wrap: wrap;
        }

        .primary-btn, .secondary-btn {
          border: none;
          cursor: pointer;
          border-radius: 12px;
          font-weight: 700;
          padding: 12px 16px;
        }

        .primary-btn {
          background: linear-gradient(135deg, var(--primary), var(--primary-2));
          color: white;
          box-shadow: 0 12px 22px rgba(99, 102, 241, 0.25);
        }

        .secondary-btn {
          background: rgba(255,255,255,0.06);
          color: var(--text);
          border: 1px solid var(--border);
        }

        .stories {
          margin-bottom: 18px;
          padding: 16px;
          display: flex;
          gap: 16px;
          overflow-x: auto;
          scrollbar-width: none;
        }

        .stories::-webkit-scrollbar {
          display: none;
        }

        .story {
          min-width: 88px;
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 8px;
          color: var(--muted);
          font-size: 0.77rem;
        }

        .story-ring {
          width: 64px;
          height: 64px;
          border-radius: 50%;
          padding: 3px;
          background: linear-gradient(135deg, var(--primary), var(--accent), var(--success));
          display: grid;
          place-items: center;
        }

        .story-ring.inactive {
          background: rgba(255,255,255,0.08);
        }

        .story-ring .inner {
          width: 100%;
          height: 100%;
          border-radius: 50%;
          background: var(--card);
          display: grid;
          place-items: center;
          font-weight: 700;
          color: var(--text);
        }

        .composer {
          padding: 16px;
          margin-bottom: 18px;
        }

        .composer-top {
          display: flex;
          align-items: center;
          gap: 12px;
          margin-bottom: 12px;
        }

        .composer textarea {
          width: 100%;
          min-height: 92px;
          resize: vertical;
          border: 1px solid var(--border);
          background: var(--bg-soft);
          color: var(--text);
          border-radius: 18px;
          padding: 14px 16px;
          outline: none;
        }

        .composer textarea::placeholder {
          color: var(--muted);
        }

        .composer-actions {
          display: flex;
          justify-content: space-between;
          align-items: center;
          gap: 12px;
          margin-top: 12px;
        }

        .toolbar {
          display: flex;
          align-items: center;
          gap: 14px;
          color: var(--muted);
          flex-wrap: wrap;
        }

        .toolbar span {
          display: flex;
          align-items: center;
          gap: 6px;
        }

        .feed-list {
          display: flex;
          flex-direction: column;
          gap: 18px;
        }

        .post {
          padding: 16px;
        }

        .post-header {
          display: flex;
          justify-content: space-between;
          gap: 10px;
        }

        .post-user {
          display: flex;
          align-items: center;
          gap: 12px;
        }

        .user-meta {
          line-height: 1.2;
        }

        .user-meta strong {
          display: block;
          font-size: 0.98rem;
        }

        .user-meta span {
          display: block;
          color: var(--muted);
          font-size: 0.8rem;
        }

        .post-content {
          margin: 14px 0 12px;
          line-height: 1.6;
          color: var(--text);
        }

        .post-image {
          width: 100%;
          height: 320px;
          object-fit: cover;
          border-radius: 18px;
          border: 1px solid var(--border);
          margin-bottom: 12px;
        }

        .post-actions {
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: 12px;
          padding-top: 12px;
          border-top: 1px solid var(--border);
          color: var(--muted);
          flex-wrap: wrap;
        }

        .action-row {
          display: flex;
          align-items: center;
          gap: 20px;
          flex-wrap: wrap;
        }

        .action-btn {
          background: transparent;
          border: none;
          color: var(--muted);
          font-weight: 700;
          cursor: pointer;
          display: inline-flex;
          align-items: center;
          gap: 7px;
          padding: 4px 0;
        }

        .action-btn.liked {
          color: #ff6b8a;
        }

        .rightbar .card {
          padding: 18px 16px;
        }

        .section-title {
          margin: 0 0 14px;
          font-size: 0.9rem;
          letter-spacing: 0.08em;
          text-transform: uppercase;
          color: var(--muted);
        }

        .trend-list, .people-list {
          display: flex;
          flex-direction: column;
          gap: 12px;
        }

        .trend-item, .person-item {
          display: flex;
          justify-content: space-between;
          align-items: center;
          gap: 10px;
          padding: 10px 10px;
          border-radius: 12px;
          background: rgba(255,255,255,0.02);
          border: 1px solid var(--border);
        }

        .trend-text strong {
          display: block;
        }

        .trend-text span {
          color: var(--muted);
          font-size: 0.8rem;
        }

        .follow-btn {
          border: none;
          background: rgba(124,156,255,0.15);
          color: var(--text);
          border-radius: 10px;
          padding: 8px 10px;
          font-weight: 700;
          cursor: pointer;
        }

        .follow-btn.following {
          background: rgba(45,212,191,0.12);
          color: var(--success);
        }

        .mini-panel {
          margin-top: 20px;
          padding: 18px 16px;
        }

        .pulse {
          display: inline-flex;
          align-items: center;
          gap: 8px;
          color: var(--success);
          font-weight: 700;
          font-size: 0.8rem;
        }

        .pulse-dot {
          width: 9px;
          height: 9px;
          border-radius: 50%;
          background: var(--success);
          box-shadow: 0 0 0 6px rgba(45, 212, 191, 0.15);
        }

        @media (max-width: 1100px) {
          .layout {
            grid-template-columns: 200px minmax(0, 1fr);
          }

          .rightbar {
            display: none;
          }
        }

        @media (max-width: 760px) {
          .layout {
            grid-template-columns: 1fr;
            padding-top: 12px;
          }

          .sidebar {
            position: static;
          }

          .hero {
            flex-direction: column;
            align-items: flex-start;
            gap: 18px;
          }

          .topbar {
            flex-wrap: wrap;
          }

          .actions {
            width: 100%;
            justify-content: space-between;
          }

          .search-wrap {
            width: 100%;
          }
        }
      `}</style>

      <div className="layout">
        <aside className="sidebar">
          <div className="card">
            <div className="brand">
              <div className="logo">S</div>
              <div className="brand-name">Socialite</div>
            </div>

            <nav className="nav">
              {[
                ["🏠", "Home", "feed"],
                ["🔎", "Explore", "explore"],
                ["🔔", "Notifications", "notifications"],
                ["💬", "Messages", "messages"],
                ["📁", "Bookmarks", "bookmarks"],
                ["⚙️", "Settings", "settings"],
              ].map(([icon, label, key]) => (
                <button
                  key={key}
                  className={`nav-item ${activeTab === key ? "active" : ""}`}
                  onClick={() => setActiveTab(key)}
                >
                  <span className="nav-icon">{icon}</span>
                  {label}
                </button>
              ))}
            </nav>

            <div className="profile-mini">
              <div className="profile-head">
                <div className="avatar">Y</div>
                <div>
                  <strong>Your Name</strong>
                  <div className="muted">@you</div>
                </div>
              </div>

              <div className="stats">
                <div className="stat-box">
                  <div className="stat-value">14.2k</div>
                  <div className="muted">Followers</div>
                </div>
                <div className="stat-box">
                  <div className="stat-value">892</div>
                  <div className="muted">Posts</div>
                </div>
                <div className="stat-box">
                  <div className="stat-value">96</div>
                  <div className="muted">Following</div>
                </div>
              </div>
            </div>
          </div>
        </aside>

        <main className="main-column">
          <div className="card topbar">
            <div className="search-wrap">
              <span>🔎</span>
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search creators, topics, or thoughts..."
              />
            </div>

            <div className="actions">
              <button className="icon-btn" aria-label="Messages">✉️</button>
              <button className="icon-btn" aria-label="Notifications">🔔</button>
              <button
                className="theme-toggle"
                onClick={() => setTheme((prev) => (prev === "dark" ? "light" : "dark"))}
              >
                {theme === "dark" ? "☀️ Light" : "🌙 Dark"}
              </button>
            </div>
          </div>

          <div className="card hero">
            <div>
              <h1>Build your community.</h1>
              <p>
                Share ideas, spark conversations, and grow a network around what matters to
                you. The best communities are built with clarity, trust, and momentum.
              </p>
            </div>

            <div className="cta-group">
              <button className="primary-btn">Create Post</button>
              <button className="secondary-btn">Go Live</button>
            </div>
          </div>

          <div className="card stories">
            {stories.map((story) => (
              <div className="story" key={story.id}>
                <div className={`story-ring ${story.active ? "" : "inactive"}`}>
                  <div className="inner">{story.avatar}</div>
                </div>
                <div>{story.user}</div>
              </div>
            ))}
          </div>

          <div className="card composer">
            <div className="composer-top">
              <div className="avatar small">Y</div>
              <div className="muted">Share something with your network</div>
            </div>

            <textarea
              value={composer}
              onChange={(e) => setComposer(e.target.value)}
              placeholder="What are you building today?"
            />

            <div className="composer-actions">
              <div className="toolbar">
                <span>📷 Photo</span>
                <span>🎥 Video</span>
                <span>📍 Location</span>
                <span>😊 Mood</span>
              </div>

              <button className="primary-btn" onClick={handleAddPost}>
                Publish
              </button>
            </div>
          </div>

          <div className="feed-list">
            {filteredPosts.length === 0 ? (
              <div className="card post">
                <h3>No matching posts found</h3>
                <p className="muted">Try another search or post something new.</p>
              </div>
            ) : (
              filteredPosts.map((post) => (
                <article className="card post" key={post.id}>
                  <div className="post-header">
                    <div className="post-user">
                      <div className="avatar small">{post.avatar}</div>
                      <div className="user-meta">
                        <strong>{post.author}</strong>
                        <span>
                          {post.handle} • {post.role} • {post.time}
                        </span>
                      </div>
                    </div>

                    <button className="icon-btn" aria-label="More">⋯</button>
                  </div>

                  <div className="post-content">{post.content}</div>

                  {post.image && <img className="post-image" src={post.image} alt="Post visual" />}

                  <div className="post-actions">
                    <div className="action-row">
                      <button
                        className={`action-btn ${post.liked ? "liked" : ""}`}
                        onClick={() => handleLike(post.id)}
                      >
                        {post.liked ? "💖" : "🤍"} {post.likes.toLocaleString()}
                      </button>
                      <button className="action-btn">💬 {post.comments.toLocaleString()}</button>
                      <button className="action-btn">🔁 {post.shares.toLocaleString()}</button>
                    </div>

                    <button className="action-btn">🔖 Save</button>
                  </div>
                </article>
              ))
            )}
          </div>
        </main>

        <aside className="rightbar">
          <div className="card">
