async function seed() {
  const communityCount = await prisma.community.count();
  if (communityCount === 0) {
    await prisma.community.createMany({ data: DEFAULT_COMMUNITIES });
  }

  const userCount = await prisma.user.count();
  if (userCount === 0) {
    const bcrypt = (await import("bcryptjs")).default;
