          ...user,
          password: await bcrypt.hash(user.password, 10),
        },
      });
    }
  }

  const postsCount = await prisma.post.count();
  if (postsCount === 0) {
    const users = await prisma.user.findMany();
    const usersByHandle = Object.fromEntries(users.map((user) => [user.handle, user]));
    const seedPosts = [
