    var(--background);
  color: var(--foreground);
  font-family: Arial, Helvetica, sans-serif;
}

button,
input {
  font: inherit;
}

img {
  display: block;
  max-width: 100%;
}

::selection {
  background: rgba(99, 102, 241, 0.45);
}

